# Create a Python helper script that extracts patterns from demos
# and provides a way to generate outputs

import json

def extract_block_patterns(demos):
    """Extract the block pattern for each unique value from demos"""
    patterns = {}  # value -> 3x3 block pattern

    for demo in demos:
        input_grid = demo['input']
        output_grid = demo['output']

        # Get unique non-zero values in input
        values = set()
        for row in input_grid:
            for cell in row:
                if cell != 0:
                    values.add(cell)

        for val in values:
            # Extract all 3x3 blocks for this value from the output
            blocks = []
            for r in range(3):
                for c in range(3):
                    if input_grid[r][c] == val:
                        block = [list(row[c*3:(c+1)*3]) for row in output_grid[r*3:(r+1)*3]]
                        blocks.append(block)

            # All blocks for same value should be identical
            if blocks:
                patterns[val] = blocks[0]

    return patterns

